// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address to, uint256 amount) public {
        vm.assume(to != address(0));
        // low-level call to a plain address always succeeds, so c.transfer completes
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool ok = c.transfer(from, to, tos, amount);
        assertTrue(ok, "successful transfer must return true");
    }
}
